package cn.blockforge.generated.generatedmod;
import cn.blockforge.generated.generatedmod.alchemy.*;
import cn.blockforge.generated.generatedmod.alchemy.research.*;
import cn.blockforge.generated.generatedmod.fixtures.GameTestPlayer;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.item.*;
import net.minecraftforge.gametest.*;
@GameTestHolder("wuxingxiantu_entry") @PrefixGameTestTemplate(false)
public final class ResearchTableGameTests {
    record F(GameTestPlayer p,ResearchTableEntity table,ResearchTableMenu menu,BlockPos pos) implements AutoCloseable{public void close(){p.serverLevel().removeBlock(pos,false);p.close();}}
    static F setup(GameTestHelper h){var pos=h.absolutePos(new BlockPos(1,2,1));h.getLevel().setBlockAndUpdate(pos,WuXingBlocks.ALCHEMY_RESEARCH_TABLE.get().defaultBlockState());var t=(ResearchTableEntity)h.getLevel().getBlockEntity(pos);var p=new GameTestPlayer(h.getLevel());p.setPos(pos.getX()+.5,pos.getY()+1,pos.getZ()+.5);FormulaKnowledge.unlock(p);t.setItem(0,PillData.create(PillCatalog.GATHER_QI,PillData.Grade.LOW,PillData.Element.METAL,0));t.setItem(1,new ItemStack(Items.PAPER,3));t.setItem(2,new ItemStack(Items.INK_SAC,3));return new F(p,t,new ResearchTableMenu(1,p.getInventory(),t),pos);}
    @GameTest(template="empty") public static void genuineMenuHas39SlotsAndAllSixPages(GameTestHelper h){try(var f=setup(h)){h.assertTrue(f.menu.slots.size()==39,"Must have 3 work slots and exactly36 player slots");for(int i=0;i<6;i++)h.assertTrue(f.menu.clickMenuButton(f.p,i)&&f.menu.page()==i,"Page navigation lost");h.assertTrue(!f.menu.clickMenuButton(f.p,6)&&!f.menu.clickMenuButton(f.p,255),"Unknown action accepted");}h.succeed();}
    @GameTest(template="empty") public static void observationRetainsSampleAndNoteChargesExactlyOnce(GameTestHelper h){try(var f=setup(h)){var sample=f.table.getItem(0).copy();h.assertTrue(f.menu.clickMenuButton(f.p,10)&&f.menu.analyzed(),"Sample inspection failed");h.assertTrue(ItemStack.matches(sample,f.table.getItem(0)),"Observation consumed or rewrote sample");h.assertTrue(f.menu.clickMenuButton(f.p,11)&&f.menu.records()==1,"Note not recorded");h.assertTrue(f.table.getItem(1).getCount()==2&&f.table.getItem(2).getCount()==2,"Wrong supply cost");h.assertTrue(!f.menu.clickMenuButton(f.p,11)&&f.table.getItem(1).getCount()==2,"Duplicate note charged again");h.assertTrue(!f.menu.lastRecord().isBlank(),"Note summary not transported");}h.succeed();}
    @GameTest(template="empty") public static void changedSampleClearsObservationAndForgedStateCannotSave(GameTestHelper h){try(var f=setup(h)){f.menu.clickMenuButton(f.p,10);f.table.setItem(0,new ItemStack(Items.DIAMOND));f.menu.broadcastChanges();h.assertTrue(!f.menu.analyzed(),"Changed item retained old observations");f.menu.setData(1,1);h.assertTrue(!f.menu.clickMenuButton(f.p,11)&&f.table.getItem(1).getCount()==3&&f.menu.records()==0,"Forged view data saved evidence");}h.succeed();}
    @GameTest(template="empty") public static void unknownV5BatchAndNonOwnerMenuRequestFailClosed(GameTestHelper h){try(var f=setup(h);var other=new GameTestPlayer(h.getLevel())){var fake=new ItemStack(WuXingItems.V5_PILL.get());fake.getOrCreateTag().putUUID(cn.blockforge.generated.generatedmod.alchemy.batch.V5Batch.KEY,java.util.UUID.randomUUID());f.table.setItem(0,fake);h.assertTrue(!f.menu.clickMenuButton(f.p,10),"Uncredentialed V5 sample authenticated");h.assertTrue(!f.menu.clickMenuButton(other,1),"Another player controlled this personal menu");}h.succeed();}
    @GameTest(template="empty") public static void missingSuppliesAndKnowledgeDoNotTakeAnything(GameTestHelper h){try(var f=setup(h)){FormulaKnowledge.reset(f.p);h.assertTrue(!f.menu.clickMenuButton(f.p,10)&&f.table.getItem(1).getCount()==3,"Locked inspection changed inputs");FormulaKnowledge.unlock(f.p);f.menu.clickMenuButton(f.p,10);f.table.setItem(2,ItemStack.EMPTY);h.assertTrue(!f.menu.clickMenuButton(f.p,11)&&f.menu.records()==0&&f.table.getItem(1).getCount()==3,"Missing ink consumed paper or wrote note");}h.succeed();}
    @GameTest(template="empty") public static void tableNbtKeepsAllThreeInputsAndRenamingDoesNotCreateEvidence(GameTestHelper h){try(var f=setup(h)){var n=f.table.saveWithoutMetadata();f.table.clearContent();f.table.load(n);h.assertTrue(f.table.getItem(0).getCount()==1&&f.table.getItem(1).getCount()==3&&f.table.getItem(2).getCount()==3,"Container reload lost inputs");var a=f.table.getItem(0).copy();var b=a.copy();b.setHoverName(net.minecraft.network.chat.Component.literal("Renamed"));h.assertTrue(ResearchView.fingerprint(a).equals(ResearchView.fingerprint(b)),"Rename produced new evidence identity");f.p.setPos(f.p.getX()+20,f.p.getY(),f.p.getZ());h.assertTrue(!f.menu.clickMenuButton(f.p,10),"Out-of-range action accepted");}h.succeed();}
}
